import React from 'react';
import ReactECharts from 'echarts-for-react';

export default function ChartCard({ insight }) {
  const { title, description, echartsConfig, queryError, noData, sql } = insight;

  const chartType = echartsConfig?.series?.[0]?.type || 'bar';
  const isPie = chartType === 'pie';

  // Build config without undefined keys — ECharts crashes if xAxis/yAxis are undefined on pie charts
  const finalConfig = {
    backgroundColor: 'transparent',
    title: {
      ...echartsConfig?.title,
      textStyle: { color: '#fff', fontSize: 14, fontWeight: '600' },
    },
    tooltip: isPie
      ? { trigger: 'item', formatter: '{b}: {c} ({d}%)', backgroundColor: 'rgba(20,20,40,0.95)', borderColor: 'rgba(255,255,255,0.1)', textStyle: { color: '#fff' } }
      : { trigger: 'axis', backgroundColor: 'rgba(20,20,40,0.95)', borderColor: 'rgba(255,255,255,0.1)', textStyle: { color: '#fff' } },
    ...(echartsConfig?.legend && {
      legend: { ...echartsConfig.legend, textStyle: { color: 'rgba(255,255,255,0.7)' } },
    }),
    ...(!isPie && {
      grid: echartsConfig?.grid || { left: '5%', right: '5%', bottom: '15%', containLabel: true },
      xAxis: {
        type: 'category',
        ...echartsConfig?.xAxis,
        axisLabel: { rotate: 30, color: 'rgba(255,255,255,0.6)', ...echartsConfig?.xAxis?.axisLabel },
        axisLine: { lineStyle: { color: 'rgba(255,255,255,0.15)' } },
        splitLine: { lineStyle: { color: 'rgba(255,255,255,0.05)' } },
      },
      yAxis: {
        type: 'value',
        ...echartsConfig?.yAxis,
        axisLabel: { color: 'rgba(255,255,255,0.6)' },
        splitLine: { lineStyle: { color: 'rgba(255,255,255,0.07)' } },
      },
    }),
    series: echartsConfig?.series?.map((s) => ({
      ...s,
      ...(s.type === 'bar' && { itemStyle: s.itemStyle || { borderRadius: [4, 4, 0, 0] } }),
      ...(s.type === 'pie' && { itemStyle: { borderRadius: 6, borderWidth: 2, borderColor: '#1a1a3e' } }),
    })),
  };

  return (
    <div style={styles.card}>
      <div style={styles.header}>
        <h3 style={styles.title}>{title}</h3>
        <p style={styles.description}>{description}</p>
      </div>

      <div style={styles.chartWrap}>
        {queryError ? (
          <div style={styles.errorBox}>
            <span style={styles.errorIcon}>⚠️</span>
            <p style={styles.errorText}>Query failed: {queryError}</p>
            <code style={styles.errorSql}>{sql}</code>
          </div>
        ) : noData ? (
          <div style={styles.emptyBox}>
            <span style={{ fontSize: 32 }}>📭</span>
            <p style={styles.emptyText}>No data returned</p>
          </div>
        ) : (
          <ReactECharts
            option={finalConfig}
            style={{ height: '280px', width: '100%' }}
            theme="dark"
            opts={{ renderer: 'canvas' }}
          />
        )}
      </div>

      <details style={styles.sqlDetails}>
        <summary style={styles.sqlSummary}>View SQL</summary>
        <pre style={styles.sqlCode}>{sql}</pre>
      </details>
    </div>
  );
}

const styles = {
  card: {
    background: 'rgba(255,255,255,0.04)',
    border: '1px solid rgba(255,255,255,0.08)',
    borderRadius: '16px',
    padding: '24px',
    display: 'flex',
    flexDirection: 'column',
    gap: '16px',
    transition: 'transform 0.2s, box-shadow 0.2s',
    boxShadow: '0 4px 24px rgba(0,0,0,0.3)',
  },
  header: {},
  title: {
    color: '#fff',
    fontSize: '16px',
    fontWeight: '700',
    margin: '0 0 6px',
    letterSpacing: '-0.2px',
  },
  description: {
    color: 'rgba(255,255,255,0.5)',
    fontSize: '13px',
    lineHeight: '1.6',
    margin: 0,
  },
  chartWrap: { minHeight: '280px', display: 'flex', alignItems: 'center', justifyContent: 'center' },
  errorBox: {
    textAlign: 'center',
    padding: '20px',
    background: 'rgba(238,102,102,0.1)',
    borderRadius: '10px',
    border: '1px solid rgba(238,102,102,0.2)',
    width: '100%',
  },
  errorIcon: { fontSize: '24px' },
  errorText: { color: '#EE6666', fontSize: '13px', margin: '8px 0' },
  errorSql: {
    color: 'rgba(255,255,255,0.4)',
    fontSize: '11px',
    fontFamily: 'monospace',
    wordBreak: 'break-all',
    whiteSpace: 'pre-wrap',
  },
  emptyBox: { textAlign: 'center', color: 'rgba(255,255,255,0.3)' },
  emptyText: { fontSize: '13px', marginTop: '8px' },
  sqlDetails: { borderTop: '1px solid rgba(255,255,255,0.06)', paddingTop: '12px' },
  sqlSummary: {
    color: 'rgba(255,255,255,0.3)',
    fontSize: '12px',
    cursor: 'pointer',
    userSelect: 'none',
    letterSpacing: '0.3px',
  },
  sqlCode: {
    marginTop: '10px',
    padding: '12px',
    background: 'rgba(0,0,0,0.3)',
    borderRadius: '8px',
    color: 'rgba(255,255,255,0.5)',
    fontSize: '12px',
    fontFamily: 'monospace',
    whiteSpace: 'pre-wrap',
    wordBreak: 'break-all',
    overflow: 'auto',
  },
};
